t.script:
(function () {
  "use strict";
  function $(sel, root){return (root||document).querySelector(sel);}
  function $val(id, d){ var el=$("#"+id); return el?el.value:d; }

  async function loadImage(src){ return new Promise(function(res,rej){ var i=new Image(); i.onload=function(){res(i)}; i.onerror=rej; i.src=src; }); }
  function readAsDataURL(f){ return new Promise(function(res,rej){ var r=new FileReader(); r.onload=function(){res(r.result)}; r.onerror=rej; r.readAsDataURL(f); }); }

  function applyTransform(){
    var logo=$("#spw_logo_preview"), base=$("#spw_product_img"); if(!logo||!base) return;
    var size=parseInt($val("spw_size","100"),10), px=parseInt($val("spw_pos_x","0"),10), py=parseInt($val("spw_pos_y","10"),10), rot=parseInt($val("spw_rotation","0"),10);
    var bw=base.clientWidth, bh=base.clientHeight;
    logo.style.position="absolute";
    logo.style.left=(bw*(0.5+px/100))+"px";
    logo.style.top =(bh*(0.6+py/100))+"px";
    logo.style.transform="translate(-50%,-50%) rotate("+rot+"deg)";
    logo.style.width=size+"px";
    logo.classList.remove("d-none");
  }

  async function renderPNGDataURL(){
    var baseEl=$("#spw-base-img"); 
    var baseSrc=(baseEl&&baseEl.getAttribute("src")) || $val("spw_img_src","") || ($("#spw_product_img")||{}).getAttribute("src");
    if(!baseSrc) throw new Error("Sin base");
    var baseIm=await loadImage(baseSrc);
    var canvas=document.createElement("canvas"), ctx=canvas.getContext("2d");
    canvas.width=baseIm.naturalWidth||baseIm.width; canvas.height=baseIm.naturalHeight||baseIm.height;
    ctx.drawImage(baseIm,0,0,canvas.width,canvas.height);

    var logoEl=$("#spw_logo_preview");
    if(logoEl && logoEl.src){
      var base=$("#spw_product_img"), bw=base.clientWidth, bh=base.clientHeight, br=base.getBoundingClientRect(), lr=logoEl.getBoundingClientRect();
      var cx=((lr.left+lr.width/2)-br.left)/bw*canvas.width, cy=((lr.top+lr.height/2)-br.top)/bh*canvas.height, w=lr.width/bw*canvas.width;
      var logoIm=await loadImage(logoEl.src), ratio=(logoIm.naturalHeight||logoIm.height)/(logoIm.naturalWidth||logoIm.width);
      var h=w*ratio, rot=(parseInt($val("spw_rotation","0"),10)*Math.PI)/180;
      ctx.save(); ctx.translate(cx,cy); ctx.rotate(rot); ctx.drawImage(logoIm,-w/2,-h/2,w,h); ctx.restore();
    }
    return canvas.toDataURL("image/png");
  }

  async function postJSON(url, payload){
    try{
      var r=await fetch(url,{method:"POST",headers:{"Content-Type":"application/json","X-Requested-With":"XMLHttpRequest"},credentials:"same-origin",body:JSON.stringify(payload)});
      var t=await r.text(); var d=null; try{d=JSON.parse(t)}catch(_){}
      return {ok: !!(d&&(d.ok===true||d.ok==="true")), data:d, status:r.status, raw:t};
    }catch(e){ return {ok:false, data:null, status:0, raw:String(e)}; }
  }
  async function postForm(url, payload){
    try{
      var fd=new FormData(); Object.keys(payload||{}).forEach(function(k){fd.append(k,payload[k])});
      var r=await fetch(url,{method:"POST",body:fd,credentials:"same-origin"}); var t=await r.text(); var d=null; try{d=JSON.parse(t)}catch(_){}
      return {ok:r.ok && (!!d ? (d.ok===true||d.ok==="true") : true), data:d||{}, status:r.status, raw:t};
    }catch(e){ return {ok:false, data:null, status:0, raw:String(e)}; }
  }

  async function addToCart(){
    var variantId=($val("spw_variant_id","")||"").trim(); if(!variantId){ alert("Falta la variante del producto."); return; }
    var qty=parseInt($val("spw_qty","1"),10)||1;
    var tech=(document.querySelector("input[name='spw_tech']:checked")||{}).value||"";
    var svgColor=(document.querySelector("input[name='spw_svg_color']:checked")||{}).value||"";
    var notes=($val("spw_notes","")||"").trim();

    var du=await renderPNGDataURL();
    try{
      sessionStorage.setItem('spw_last_product_id', String(variantId));
      sessionStorage.setItem('spw_last_png', du||'');
      sessionStorage.setItem('spw_last_color', svgColor||'');
    }catch(_){}

    var r1=await postJSON("/spw/add_to_cart_meta",{variant_id:parseInt(variantId,10),qty:qty,tech:tech,svg_color:svgColor,notes:notes});
    if(!r1.ok){ r1=await postForm("/spw/add_to_cart_meta_http",{variant_id:variantId,qty:qty,tech:tech,svg_color:svgColor,notes:notes}); }
    if(!r1.ok){ alert((r1.data&&r1.data.message)?r1.data.message:"No se pudo añadir al carrito."); return; }

    try{ if(r1.data && r1.data.line_id){ sessionStorage.setItem('spw_last_line_id', String(r1.data.line_id)); } }catch(_){}
    try{
      var b64=(du.split('base64,')[1]||""); if(b64){
        var r2=await postJSON("/spw/attach_png",{line_id:r1.data.line_id,png_b64:b64});
        if(!r2.ok){ await postForm("/spw/attach_png_http",{line_id:r1.data.line_id,png_b64:b64}); }
      }
    }catch(_){}

    var baseUrl=(r1.data&&r1.data.cart_url)||"/shop/cart";
    var goto=(r1.data&&r1.data.line_id)?(baseUrl+(baseUrl.indexOf('?')===-1?'?':'&')+'spw_line_id='+encodeURIComponent(r1.data.line_id)):baseUrl;
    window.location.href=goto;
  }

  async function downloadPNGiOSSafe(){
    try{
      var dataUrl=await renderPNGDataURL();
      var a=document.createElement("a"); a.href=dataUrl; a.download="personalizacion.png";
      if(typeof a.download==="undefined"){ window.location.href=dataUrl; } else { document.body.appendChild(a); a.click(); a.remove(); }
    }catch(_){ alert("No se pudo generar el PNG."); }
  }

  function init(){
    var inFile=document.getElementById("spw_logo_input"), logo=document.getElementById("spw_logo_preview");
    if(inFile){ inFile.addEventListener("change", async function(ev){ var f=ev.target.files&&ev.target.files[0]; if(!f) return; logo.src=await readAsDataURL(f); applyTransform(); }); }
    ["spw_size","spw_pos_x","spw_pos_y","spw_rotation"].forEach(function(id){ var el=document.getElementById(id); if(el) el.addEventListener("input", applyTransform); });
    window.spwReset=function(){ document.getElementById("spw_size").value=100; document.getElementById("spw_pos_x").value=0; document.getElementById("spw_pos_y").value=10; document.getElementById("spw_rotation").value=0; applyTransform(); };
    var dl=document.getElementById("spw_download_png"); if(dl){ dl.addEventListener("click", downloadPNGiOSSafe); }
    var add=document.getElementById("spw_add_to_cart"); if(add){ add.addEventListener("click", addToCart); }
    applyTransform();
  }
  if(document.readyState==="loading"){ document.addEventListener("DOMContentLoaded", init); } else { init(); }
})();

xpath.script:
(function(){
  "use strict";

  function q(s,r){return (r||document).querySelector(s);}
  function qa(s,r){return Array.from((r||document).querySelectorAll(s));}
  function getParam(n){ try{ return new URL(location.href).searchParams.get(n); }catch(_){ return null; } }

  function descContainer(line){
    var meta=(function(){
      var nodes=qa("p,div,li,span", line);
      return nodes.find(function(el){
        var t=(el.textContent||"").toLowerCase();
        return /t[eé]cnica/.test(t) || /color\s*svg/.test(t) || /color\s*#/.test(t);
      })||null;
    })();
    if(meta) return meta;
    return q(".media-body", line)
        || q(".flex-grow-1", line)
        || q(".o_wsale_cart_description", line)
        || q(".o_cart_description", line)
        || q(".card-body", line)
        || q(".col", line)
        || line;
  }

  function lineIdOf(line){
    if(!line) return null;
    try{
      return line.getAttribute("data-line-id")
        || (q('input[name=\"line_id\"]', line)||{}).value
        || (function(){
             var a=line.closest('a[href*=\"line_id=\"]')||q('a[href*=\"line_id=\"]', line);
             if(!a) return null; var u=new URL(a.getAttribute('href'), location.origin); return u.searchParams.get('line_id');
           })()
        || null;
    }catch(_){ return null; }
  }

  function parseHex(text){
    var m=(text||\"\").match(/#([0-9a-fA-F]{6})\\b/);
    return m?('#'+m[1]):null;
  }

  function insertPreview(line, src, id, colorHex){
    try{
      qa('.spw-preview', line).forEach(function(n){ n.remove(); });

      var target=descContainer(line);
      var wrap=document.createElement('div');
      wrap.className='spw-preview';
      wrap.setAttribute('data-line', id||'');
      wrap.style.display='inline-flex';
      wrap.style.alignItems='center';
      wrap.style.gap='8px';
      wrap.style.marginTop='6px';
      wrap.style.maxWidth='100%';

      var img=new Image();
      img.alt='Personalización';
      img.loading='lazy';
      img.src=src;
      img.style.maxWidth='120px';
      img.style.height='auto';
      img.style.border='1px solid #e5e7eb';
      img.style.borderRadius='6px';
      img.onerror=function(){ wrap.remove(); };
      wrap.appendChild(img);

      var sw=colorHex || parseHex(target.textContent || line.textContent || '');
      if(sw && /^#[0-9A-F]{6}$/i.test(sw)){
        var dot=document.createElement('span');
        dot.title=sw;
        dot.style.display='inline-block';
        dot.style.width='14px';
        dot.style.height='14px';
        dot.style.borderRadius='999px';
        dot.style.border='1px solid #e5e7eb';
        dot.style.background=sw;
        wrap.appendChild(dot);
      }

      if(target && target.parentElement){
        target.insertAdjacentElement('afterend', wrap);
      }else{
        line.appendChild(wrap);
      }
    }catch(_){}
  }

  function findLines(){
    var sel='.o_wsale_cart_item, tr.js_cart_line, .card.js_cart_item, .o_cart_line, [data-line-id]';
    return qa(sel, document).filter(Boolean);
  }

  function inject(){
    try{
      if(!/\\/shop\\/cart/.test(location.pathname)) return;

      var wanted=getParam('spw_line_id');
      var lastId=null,lastPng=null,lastColor=null;
      try{
        lastId  = sessionStorage.getItem('spw_last_line_id');
        lastPng = sessionStorage.getItem('spw_last_png');
        lastColor = sessionStorage.getItem('spw_last_color');
      }catch(_){}

      var lines=findLines(); if(!lines.length) return;

      qa('.spw-preview').forEach(function(el){
        var keep = lines.some(function(ln){ return ln.contains(el); });
        if(!keep) el.remove();
      });

      lines.forEach(function(line){
        var id=lineIdOf(line); if(!id) return;

        if(wanted && lastId && id===lastId && lastPng){
          insertPreview(line, lastPng, id, lastColor);
          return;
        }
        insertPreview(line, '/spw/line_preview/'+encodeURIComponent(id)+'.png?_='+Date.now(), id, null);
      });

      if(wanted && lastId && wanted===lastId){
        try{
          sessionStorage.removeItem('spw_last_line_id');
          sessionStorage.removeItem('spw_last_png');
          sessionStorage.removeItem('spw_last_color');
        }catch(_){}
      }
    }catch(_){}
  }

  function boot(){
    inject();
    var root=document.body;
    if(window.MutationObserver && root){
      var rafId=null;
      var mo=new MutationObserver(function(){
        if(rafId) cancelAnimationFrame(rafId);
        rafId=requestAnimationFrame(inject);
      });
      mo.observe(root,{childList:true,subtree:true});
    }
    setTimeout(inject,200);
    setTimeout(inject,600);
    setTimeout(inject,1400);
    window.addEventListener('pageshow', inject);
  }

  if(document.readyState==='loading'){ document.addEventListener('DOMContentLoaded', boot); } else { boot(); }
})();
